import React, { useState, useEffect } from "react";
import {
  Box,
  Modal,
  Typography,
  TextField,
  Button,
  MenuItem,
  CircularProgress,
} from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import {
  getAllBuyerCategories,
} from "../redux/slices/buyerCategoriesSlice";
import { createBuyerSellerConnection } from "../redux/slices/buyerNetworkSlice";

const FindNewBuyerModal = ({ open, onClose }) => {
  const dispatch = useDispatch();

  const [emailOrPhone, setEmailOrPhone] = useState("");
  const [category, setCategory] = useState("");
  const [loading, setLoading] = useState(false);

  // ✅ Get buyer categories from Redux
  const { categories: buyerCategories, loading: categoriesLoading } = useSelector(
    (state) => state.buyerCategories
  );


    // const {
    //   categories: buyerCategories,
  
    //   loading: categoriesLoading 
    // } = useSelector((state) => state.buyerCategories);

      console.log(buyerCategories, "buyerCategories")
  // ✅ Fetch categories when modal opens
  useEffect(() => {
    if (open) {
      dispatch(getAllBuyerCategories());
    }
  }, [dispatch, open]);

  // ✅ Handle submit - call createBuyerSellerConnection API
  const handleSubmit = async () => {
    if (!emailOrPhone || !category) return;

    setLoading(true);

    // Split input (decide if it's email or phone)
    const isEmail = emailOrPhone.includes("@");
    const payload = {
      buyerEmail: isEmail ? emailOrPhone : null,
      buyerPhone: !isEmail ? emailOrPhone : null,
      buyerCategory: category,
    };

    try {
      const resultAction = await dispatch(createBuyerSellerConnection(payload));

      if (createBuyerSellerConnection.fulfilled.match(resultAction)) {
        console.log("✅ Connection created:", resultAction.payload);
      } else {
        console.error("❌ Failed:", resultAction.payload);
      }
      onClose();
    } catch (err) {
      console.error("Error submitting:", err);
    } finally {
      setLoading(false);
      setEmailOrPhone("");
      setCategory("");
    }
  };

  return (
    <Modal open={open} onClose={onClose}>
      <Box
        sx={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          bgcolor: "background.paper",
          borderRadius: 3,
          boxShadow: 24,
          p: 4,
          width: { xs: "90%", sm: 420 },
        }}
      >
        <Typography
          variant="h6"
          fontWeight={700}
          sx={{ mb: 2, textAlign: "center" }}
        >
          Find New Buyer
        </Typography>

        {/* Email / Phone Field */}
        <TextField
          fullWidth
          label="Email or Phone Number"
          value={emailOrPhone}
          onChange={(e) => setEmailOrPhone(e.target.value)}
          sx={{ mb: 3 }}
        />

        {/* Category Dropdown */}
        <TextField
          select
          fullWidth
          label="Select Buyer Category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
          sx={{ mb: 3 }}
        >
          {categoriesLoading ? (
            <MenuItem disabled>Loading...</MenuItem>
          ) : buyerCategories && buyerCategories.length > 0 ? (
            buyerCategories.map((cat) => (
              <MenuItem key={cat._id} value={cat._id}>
                {cat.name}
              </MenuItem>
            ))
          ) : (
            <MenuItem disabled>No categories found</MenuItem>
          )}
        </TextField>

        {/* Submit Button */}
        <Button
          fullWidth
          variant="contained"
          sx={{
            bgcolor: "#3066be",
            borderRadius: 2,
            fontWeight: 600,
            fontSize: 15,
            py: 1.2,
            "&:hover": { bgcolor: "#2959a6" },
          }}
          onClick={handleSubmit}
          disabled={loading || !emailOrPhone || !category}
        >
          {loading ? (
            <CircularProgress size={24} sx={{ color: "#fff" }} />
          ) : (
            "Submit"
          )}
        </Button>
      </Box>
    </Modal>
  );
};

export default FindNewBuyerModal;
