import React, { useEffect, useState } from "react";
import {
  Box,
  Grid,
  Typography,
  Avatar,
  useTheme,
  useMediaQuery,
  Card,
  CardContent,
  Rating,
  CircularProgress,
  Button,
  Container,
} from "@mui/material";
import { motion } from "framer-motion";
import FormatQuoteIcon from '@mui/icons-material/FormatQuote';
import { Link as RouterLink } from "react-router-dom"; // Import Link for navigation

// --- MOCK TESTIMONIALS (SAMPLE DATA) ---
const mockTestimonials = Array.from({ length: 20 }, (_, i) => ({
  id: i + 1,
  name: `Customer Name ${i + 1}`,
  role: i % 3 === 0 ? "Startup Founder" : (i % 3 === 1 ? "Marketing Head" : "Tech Lead"),
  avatar: `https://i.pravatar.cc/150?img=${i + 1}`,
  quote: "BizBridge has completely transformed our workflow. Their tools are intuitive and powerful, saving us countless hours. Highly recommended for any growing business!",
  rating: 4.5 + (i % 5) / 10,
}));

// --- Animation variants for Framer Motion ---
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.5,
    },
  },
};

const TestimonialSectionHome = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    // Simulate API call
    const timer = setTimeout(() => {
      setTestimonials(mockTestimonials);
      setLoading(false);
    }, 1500);

    return () => clearTimeout(timer);
  }, []);

  // Show only the first 4 testimonials on the home page
  const visibleTestimonials = testimonials.slice(0, 4);

  return (
    <Box
      sx={{
        width: "100%",
        bgcolor: "#f9fafb",
        py: { xs: 6, md: 10 },
        px: { xs: 2, sm: 4 },
      }}
    >
      <Container maxWidth="lg">
        {/* Section Title */}
        <Box textAlign="center" mb={{ xs: 5, md: 8 }}>
          <Typography
            variant="h3"
            component="h2"
            sx={{ fontWeight: 800, color: '#101828', fontSize: { xs: '2rem', sm: '2.5rem', md: '3rem' } }}
          >
            What Our <Box component="span" sx={{ color: '#28a745' }}>Clients Say</Box>
          </Typography>
          <Typography
            variant="body1"
            sx={{ color: 'text.secondary', mt: 2, maxWidth: '700px', mx: 'auto', fontSize: { xs: '1rem', md: '1.125rem' } }}
          >
            Discover how businesses like yours have achieved success and growth by partnering with BizBridge. Real stories, real results.
          </Typography>
        </Box>

        {loading && (
          <Box textAlign="center" sx={{ py: 6 }}>
            <CircularProgress />
            <Typography sx={{ mt: 2 }}>Loading Testimonials...</Typography>
          </Box>
        )}

        {!loading && (
          <>
            <motion.div
              variants={containerVariants}
              initial="hidden"
              animate="visible"
            >
              <Grid
                container
                spacing={isMobile ? 3 : 4}
                justifyContent="center"
                alignItems="stretch"
              >
                {visibleTestimonials.map((t) => (
                  <Grid item xs={12} sm={6} md={3} key={t.id}>
                    <motion.div variants={itemVariants} style={{ height: '100%' }}>
                      <Card
                        sx={{
                          height: "100%",
                          borderRadius: "16px",
                          boxShadow: "none",
                          border: "1px solid #e5e7eb",
                          display: 'flex',
                          flexDirection: 'column',
                          transition: 'transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease',
                          '&:hover': {
                            transform: 'translateY(-8px)',
                            boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1)',
                            borderColor: '#28a745',
                          }
                        }}
                      >
                        <CardContent sx={{ textAlign: "left", p: 3, flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                           <FormatQuoteIcon sx={{ color: '#28a745', fontSize: 40, mb: 2 }} />
                          <Typography
                            variant="body2"
                            color="#374151"
                            sx={{ fontStyle: 'italic', mb: 2, flexGrow: 1 }}
                          >
                            {`"${t.quote}"`}
                          </Typography>
                          
                          <Box sx={{ mt: 'auto' }}>
                            <Rating value={t.rating} readOnly precision={0.5} size="small" sx={{ mb: 1 }} />
                            <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                              <Avatar
                                src={t.avatar}
                                alt={t.name}
                                sx={{ width: 48, height: 48 }}
                              />
                              <Box>
                                <Typography variant="subtitle2" fontWeight={700}>
                                  {t.name}
                                </Typography>
                                <Typography variant="caption" color="text.secondary">
                                  {t.role}
                                </Typography>
                              </Box>
                            </Box>
                          </Box>
                        </CardContent>
                      </Card>
                    </motion.div>
                  </Grid>
                ))}
              </Grid>
            </motion.div>

            {/* "Load More" button that links to the testimonials page */}
            <Box textAlign="center" sx={{ mt: 6 }}>
              <Button
                component={RouterLink}
                to="/testimonials" // Link to your full testimonials page
                variant="contained"
                sx={{
                  borderRadius: "50px",
                  px: 5,
                  py: 1.5,
                  fontWeight: 600,
                  bgcolor: '#28a745',
                  color: '#fff',
                  textTransform: 'none',
                  fontSize: '1rem',
                  boxShadow: '0 4px 12px rgba(40, 167, 69, 0.3)',
                  '&:hover': {
                    bgcolor: '#218838',
                    boxShadow: '0 6px 16px rgba(40, 167, 69, 0.4)',
                    transform: 'translateY(-2px)'
                  }
                }}
              >
                View All Testimonials
              </Button>
            </Box>
          </>
        )}
      </Container>
    </Box>
  );
};

export default TestimonialSectionHome;