// src/Components/OurClients.jsx
import React, { useEffect } from "react";
import { Box, Typography, Card, CardMedia, Grid } from "@mui/material";
import Slider from "react-slick";
import { useDispatch, useSelector } from "react-redux";
import { getAllBrands } from "../redux/slices/brandsSlice"; // import thunk
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const OurClients = () => {
  const dispatch = useDispatch();
  const { items: brands, loading, error } = useSelector((state) => state.brands);

  useEffect(() => {
    dispatch(getAllBrands());
  }, [dispatch]);

  const sliderSettings = {
    infinite: true,
    speed: 600,
    slidesToShow: 2,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 2500,
    arrows: false,
    responsive: [
      { breakpoint: 768, settings: { slidesToShow: 2 } },
      { breakpoint: 480, settings: { slidesToShow: 1 } },
    ],
  };

  return (
    <Box sx={{ mt: 12, mb: 12, px: { xs: 2, md: 10 } }}>
      {/* Section Heading */}
      <Box sx={{ textAlign: "center", mb: 6 }}>
        <Typography
          variant="h2"
          sx={{
            fontWeight: 800,
            mb: 2,
            fontSize: { xs: "2rem", sm: "2.5rem", md: "3rem", lg: "3.5rem" },
          }}
        >
          <Box component="span" sx={{ color: "#000" }}>
            Brands We Have{" "}
          </Box>
          <Box component="span" sx={{ color: "#28a745" }}>
            Worked With
          </Box>
        </Typography>

        <Typography
          variant="body1"
          sx={{
            color: "#555",
            fontSize: { xs: "1rem", md: "1.1rem" },
            maxWidth: 800,
            mx: "auto",
            lineHeight: 1.6,
          }}
        >
          From local startups to top enterprises, BizBridge has partnered with
          amazing brands to deliver solutions that drive growth and success.
        </Typography>
      </Box>

      {/* Loader or Error */}
      {loading && <Typography align="center">Loading...</Typography>}
      {error && <Typography color="error" align="center">{error}</Typography>}

      {/* Mobile Carousel */}
      <Box sx={{ display: { xs: "block", md: "none" } }}>
        <Slider {...sliderSettings}>
          {brands?.map((brand) => (
            <Box key={brand._id} sx={{ textAlign: "center", p: 2 }}>
              <Card
                sx={{
                  boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
                  borderRadius: 3,
                  p: 2,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  backgroundColor: "#fff",
                  transition: "transform 0.3s ease",
                  "&:hover": { transform: "scale(1.05)" },
                }}
              >
                <CardMedia
                  component="img"
                  image={brand.image}
                  alt={`Brand ${brand._id}`}
                  sx={{ height: 120, objectFit: "contain" }}
                />
              </Card>
            </Box>
          ))}
        </Slider>
      </Box>

      {/* Desktop Grid */}
      <Grid
        container
        spacing={4}
        sx={{ display: { xs: "none", md: "flex" }, justifyContent: "center" }}
      >
        {brands?.map((brand) => (
          <Grid
            item
            xs={6}
            sm={4}
            md={2}
            key={brand._id}
            sx={{ display: "flex", justifyContent: "center" }}
          >
            <Card
              sx={{
                width: "100%",
                maxWidth: 160,
                p: 2,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                boxShadow: "0 6px 20px rgba(0,0,0,0.08)",
                borderRadius: 3,
                transition: "transform 0.3s ease, box-shadow 0.3s ease",
                "&:hover": {
                  transform: "scale(1.08)",
                  boxShadow: "0 10px 30px rgba(0,0,0,0.15)",
                },
              }}
            >
              <CardMedia
                component="img"
                image={brand.image}
                alt={`Brand ${brand._id}`}
                sx={{ height: 80, objectFit: "contain" }}
              />
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

export default OurClients;
