import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Button,
  Table,
  TableHead,
  TableRow,
  TableBody,
  TableCell,
  IconButton,
  Switch,
  TextField,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  MenuItem,
  useTheme,
  InputAdornment,
  useMediaQuery,
  TableContainer,
  Menu,
  ListItemIcon,
  ListItemText,
} from "@mui/material";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import CloudUploadOutlinedIcon from "@mui/icons-material/CloudUploadOutlined";
import MoreHorizIcon from "@mui/icons-material/MoreHoriz";
import AddIcon from "@mui/icons-material/Add";
import CloseIcon from "@mui/icons-material/Close";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddBuyerCategoryDialog from "./AddBuyerCategoryDialog";
import AddSellerCategoryDialog from "./AddSellerCategoryDialog";
import { useDispatch, useSelector } from "react-redux";
import {
  getAllBuyerCategories,
  createBuyerCategory,
} from "../redux/slices/buyerCategoriesSlice";
import {
  getAllSellerCategories,
  createSellerCategory,
} from "../redux/slices/sellerCategoriesSlice";
import {
  getUserProducts,
  addProduct,
  updateProduct,
  deleteProduct,
  getProductsByBuyerCategoryId,
  updateProductBuyerCategoryVisibility,
} from "../redux/slices/sellerProductSlice";

export default function Catalog() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.user);
  const [productsByBuyerCategory, setProductsByBuyerCategory] = useState([]);
  const [selectedBuyerCategoryId, setSelectedBuyerCategoryId] = useState(null);
  // Selected buyer category tab
  const [selectedBuyerCategory, setSelectedBuyerCategory] =
    useState("MRP Catalog"); // useState("MRP Catalog");

  // Redux state for buyer categories
  const {
    categories: buyerCategories,
    loading,
    error,
  } = useSelector((state) => state.buyerCategories);

  useEffect(() => {
    dispatch(getAllBuyerCategories());
  }, [dispatch]);

  useEffect(() => {
    const category = buyerCategories.find(
      (b) => b.name === selectedBuyerCategory
    );
    if (category) {
      // fetchProductsByBuyerCategory(category._id);
    } else {
      setProductsByBuyerCategory([]);
    }
  }, [selectedBuyerCategory, buyerCategories]);

  const {
    categories: sellerCategories,
    loading: sellerLoading,
    error: sellerError,
  } = useSelector((state) => state.sellerCategory);

  useEffect(() => {
    dispatch(getAllSellerCategories());
  }, [dispatch]);

  const { userProducts, loading: productLoading } = useSelector(
    (state) => state.products
  );

  useEffect(() => {
    dispatch(getUserProducts()); // Fetch all products or implement pagination
  }, [dispatch]);

  // Current buyer category object
  const currentBuyer = buyerCategories.find(
    (b) => b.name === selectedBuyerCategory
  );

  const categories =
    selectedBuyerCategory === "MRP Catalog"
      ? Array.from(new Set(sellerCategories.map((c) => c.name))) // <- okay, strings here
      : currentBuyer
      ? sellerCategories
          .filter((c) => c.buyerCategory === selectedBuyerCategory)
          .map((c) => c.name)
      : [];

  // Add Product form dynamic categories based on selected buyerCategory
  const [addProductCategories, setAddProductCategories] = useState([]);

  // State for selected category in filter
  const [selectedCategory, setSelectedCategory] = useState("All");

  // States for dialogs
  const [openAddProduct, setOpenAddProduct] = useState(false);
  const [openAddBuyerCategory, setOpenAddBuyerCategory] = useState(false);
  const [openAddProductCategory, setOpenAddProductCategory] = useState(false);

  // Add Product form state (includes buyerCategory)
  const [newProduct, setNewProduct] = useState({
    name: "",
    category: "",
    mrp: "",
    stock: "",
    description: "",
    specifications: "",
    image: "",
    imageFile: null, // For file upload
    // buyerCategory: selectedBuyerCategory,
  });

  // Add Buyer Category form state (discount instead of gst)
  const [newBuyerCategory, setNewBuyerCategory] = useState({
    name: "",
    discount: "",
  });
  // Limit buyer categories (excluding MRP Catalog which is always shown separately)
  const visibleCategories = buyerCategories.slice(0, 4); // first 4 categories
  const extraCategories = buyerCategories.slice(4); // rest go into "More"
  const [anchorMore, setAnchorMore] = useState(null);
  const handleMoreOpen = (e) => setAnchorMore(e.currentTarget);
  const handleMoreClose = () => setAnchorMore(null);

  // Add Product Category form state (includes gst)
  const [newProductCategory, setNewProductCategory] = useState({
    name: "",
    gst: "",
  });
  const [anchorMoreSeller, setAnchorMoreSeller] = useState(null);
  const handleMoreSellerOpen = (e) => setAnchorMoreSeller(e.currentTarget);
  const handleMoreSellerClose = () => setAnchorMoreSeller(null);

  const visibleSellerCategories = sellerCategories.slice(0, 4);
  const extraSellerCategories = sellerCategories.slice(4);

  // Edit Product form states (unchanged)
  const [editProductId, setEditProductId] = useState(null);
  const [editProduct, setEditProduct] = useState({
    name: "",
    // buyerCategory: null,
    category: null,
    mrp: "",
    price: "",
    stock: "",
    description: "",
    specifications: "",
    image: "",
    imageFile: null, // Add this field
  });
  const [openEditProduct, setOpenEditProduct] = useState(false);

  // Actions menu state
  const [anchorEl, setAnchorEl] = useState(null);
  const [actionProductId, setActionProductId] = useState(null);

  // Update addProductCategories whenever buyer category changes
  useEffect(() => {
    if (!newProduct.buyerCategory === "MRP Catalog") return;

    const buyerId = newProduct.buyerCategory;
    const filteredCategories = sellerCategories.filter(
      (c) => c.buyerCategory === buyerId
    );

    setAddProductCategories(filteredCategories);
    setNewProduct((prev) => ({ ...prev, category: "" }));
  }, [newProduct.buyerCategory, sellerCategories]);

  const filteredProducts =
    selectedCategory === "All"
      ? userProducts
      : selectedBuyerCategory === "MRP Catalog"
      ? userProducts.filter((p) => p.category?.name === selectedCategory?.name)
      : userProducts.filter(
          (p) =>
            p.buyerCategory?.name === selectedBuyerCategory &&
            p.category?.name === selectedCategory?.name
        );

  // Handlers for Add Product Dialog
  const handleAddProductOpen = () => {
    setNewProduct({
      name: "",
      category: "",
      mrp: "",
      stock: "",
      description: "",
      specifications: "",
      image: "",
      imageFile: null,
    });
    setOpenAddProduct(true);
  };

  const handleAddProductClose = () => {
    setOpenAddProduct(false);
    setNewProduct({
      name: "",
      category: "",
      mrp: "",
      stock: "",
      description: "",
      specifications: "",
      image: "",
      imageFile: null,
    });
  };

  const handleAddProductChange = (e) => {
    const { name, value, type, checked } = e.target;
    setNewProduct((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  // Add Product submit handler with image upload
  const handleAddProductSubmit = async (e) => {
    e.preventDefault();
    if (
      !newProduct.name ||
      !newProduct.category ||
      !newProduct.mrp ||
      !newProduct.stock
    ) {
      alert("Please fill all fields");
      return;
    }

    const formData = new FormData();
    formData.append("name", newProduct.name);
    formData.append("category", newProduct.category);
    formData.append("mrp", newProduct.mrp);
    formData.append("stock", newProduct.stock);
    formData.append("description", newProduct.description || "");
    formData.append("specifications", newProduct.specifications || "");
    // formData.append("buyerCategory", newProduct.buyerCategory);
    formData.append("user", user?._id);
    formData.append("image", newProduct.image); // If you handle image upload
    try {
      await dispatch(addProduct(formData)).unwrap();
      handleAddProductClose();
    } catch (err) {
      alert(err?.message || "Failed to add product");
    }
  };

  // Edit product handlers
  const handleEditProductOpen = (product) => {
    // Find the buyer category price
    const buyerProduct = productsByBuyerCategory?.products?.find(
      (p) => p._id === product._id
    );

    const priceToShow = buyerProduct?.buyerCategory?.price ?? product.price;

    // Set editProduct with buyer category price
    setEditProduct({
      ...product,
      price: priceToShow,
    });

    setEditProductId(product?._id);
    setOpenEditProduct(true);
    setAnchorEl(null);
    setActionProductId(null);
  };

  const handleEditProductClose = () => {
    setOpenEditProduct(false);
    setEditProductId(null);
    setEditProduct({
      name: "",
      category: "",
      price: "",
      stock: "",
    });
  };

  const handleEditProductChange = (e) => {
    const { name, value, type, checked } = e.target;
    setEditProduct((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  // Edit product submit handler with image upload
  const handleEditProductSubmit = async (e) => {
    e.preventDefault();

    try {
      if (
        !editProduct.name ||
        !editProduct.category ||
        !editProduct.price ||
        !editProduct.stock
      ) {
        alert("Please fill all required fields");
        return;
      }

      const categoryId = editProduct.category?._id || editProduct.category;

      if (!categoryId) {
        alert("Please select valid categories");
        return;
      }

      // Buyer Category validation
      if (!selectedBuyerCategoryId) {
        alert("Please select a valid buyer category");
        return;
      }

      const formData = new FormData();
      formData.append("name", editProduct.name || "");
      formData.append("category", categoryId);
      formData.append("mrp", editProduct.mrp?.toString() || "0");
      formData.append("price", editProduct.price?.toString() || "0");
      formData.append("stock", editProduct.stock?.toString() || "0");
      formData.append("user", user?._id || "");
      formData.append("description", editProduct.description || "");
      formData.append("specifications", editProduct.specifications || "");
      formData.append("buyerCategory", selectedBuyerCategoryId || "");

      if (editProduct.imageFile) {
        const reader = new FileReader();
        reader.onloadend = async () => {
          formData.append("image", reader.result); // Base64 string
          try {
            await dispatch(
              updateProduct({ id: editProductId, formData })
            ).unwrap();
            handleEditProductClose();

            if (editProduct.image && editProduct.image.startsWith("blob:")) {
              URL.revokeObjectURL(editProduct.image);
            }
          } catch (err) {
            console.error("Update product error:", err);
            alert(err?.message || "Failed to update product");
          }
        };
        reader.readAsDataURL(editProduct.imageFile);
        return;
      }

      if (editProduct.image) {
        formData.append("image", editProduct.image);
      }

      // FormData contents check
      console.log("FormData contents:");
      for (let [key, value] of formData.entries()) {
        console.log(key, ":", value);
      }
      await dispatch(updateProduct({ id: editProductId, formData })).unwrap();
      handleEditProductClose();
    } catch (err) {
      console.error("Update product error:", err);
      alert(err?.message || "Failed to update product");
    }
  };

  // Actions menu handlers
  const handleActionsMenuOpen = (event, id) => {
    setAnchorEl(event.currentTarget);
    setActionProductId(id);
  };

  const handleActionsMenuClose = () => {
    setAnchorEl(null);
    setActionProductId(null);
  };

  // Toggle product visibility handler
  // const handleToggleProductVisible = async (
  //   productId,
  //   currentVisibility,
  //   buyerCategoryId
  // ) => {
  //   try {
  //     const newVisibility = !currentVisibility;
  //     console.log("Toggling visibility:", newVisibility);

  //    console.log("Updating visibility for product:", {
  //       productId,
  //       buyerCategoryId,
  //       visible: currentVisibility,
  //     });
  //     await dispatch(
  //       updateProductBuyerCategoryVisibility({
  //         productId,
  //         buyerCategory: buyerCategoryId,
  //         visible: newVisibility,
  //       })
  //     ).unwrap();

  //     // Update local state so UI reflects change immediately
  //     setProductsByBuyerCategory((prev) => ({
  //       ...prev,
  //       products: prev.products.map((p) =>
  //         p._id === productId ? { ...p, productVisibility: newVisibility } : p
  //       ),
  //     }));

  //     console.log("Product visibility updated successfully");
  //   } catch (error) {
  //     console.error("Error updating product visibility:", error);
  //   }
  // };

  const handleToggleProductVisible = async (
    productId,
    currentVisibility,
    buyerCategoryId
  ) => {
    try {
      const safeVisibility = !!currentVisibility; // force boolean
      const newVisibility = !safeVisibility;

      await dispatch(
        updateProductBuyerCategoryVisibility({
          productId,
          buyerCategory: buyerCategoryId,
          visible: newVisibility,
        })
      ).unwrap();

      setProductsByBuyerCategory((prev) => ({
        ...prev,
        products: prev.products.map((p) =>
          p._id === productId ? { ...p, productVisibility: newVisibility } : p
        ),
      }));

      console.log("Product visibility updated successfully:", newVisibility);
    } catch (error) {
      console.error("Error updating product visibility:", error);
    }
  };

  // Buyer category selection handler
  const handleBuyerCategorySelect = async (category) => {
    setSelectedBuyerCategory(category.name || category); // update name for UI
    setSelectedBuyerCategoryId(category._id); // store ID for API calls
    setSelectedCategory("All");
    if (category._id) {
      // call API only for actual buyer categories
      dispatch(getProductsByBuyerCategoryId(category._id));
    }
  };

  useEffect(() => {
    if (selectedBuyerCategoryId) {
      const fetchProducts = async () => {
        try {
          const resultAction = await dispatch(
            getProductsByBuyerCategoryId(selectedBuyerCategoryId)
          ).unwrap();
          setProductsByBuyerCategory(resultAction || []);
        } catch (err) {
          console.error("Failed to fetch products by buyer category:", err);
        }
      };
      fetchProducts();
    } else {
      setProductsByBuyerCategory([]);
    }
  }, [selectedBuyerCategoryId, dispatch]);

  // Add Buyer Category handlers with Discount instead of GST
  const handleAddBuyerCategoryOpen = () => setOpenAddBuyerCategory(true);
  const handleAddBuyerCategoryClose = () => {
    setOpenAddBuyerCategory(false);
    setNewBuyerCategory({ name: "", discount: "" });
  };

  const handleAddBuyerCategoryChange = (e) => {
    const { name, value } = e.target;
    setNewBuyerCategory((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAddBuyerCategorySubmit = async (e) => {
    e.preventDefault();
    if (!newBuyerCategory.name || newBuyerCategory.discount === "") {
      alert("Please fill all fields");
      return;
    }
    // dispatch API call
    dispatch(createBuyerCategory(newBuyerCategory));
    handleAddBuyerCategoryClose();
  };

  // Add Product Category handlers with GST field
  const handleAddProductCategoryOpen = () => setOpenAddProductCategory(true);
  const handleAddProductCategoryClose = () => {
    setOpenAddProductCategory(false);
    setNewProductCategory({ name: "", gst: "" });
  };

  const handleAddProductCategoryChange = (e) => {
    const { name, value } = e.target;
    setNewProductCategory((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAddProductCategorySubmit = (e) => {
    e.preventDefault();
    if (!newProductCategory.name || newProductCategory.gst === "") {
      alert("Please fill all fields");
      return;
    }
    if (categories?.includes(newProductCategory?.name)) {
      alert("This category already exists in current buyer category");
      return;
    }

    // Dispatch Redux update
    dispatch(createSellerCategory(newProductCategory));
    dispatch(getAllSellerCategories());

    handleAddProductCategoryClose();
  };

  // Delete product handler
  const handleDeleteProduct = async (id) => {
    if (!window.confirm("Are you sure you want to delete this product?"))
      return;

    try {
      await dispatch(deleteProduct(id)).unwrap();
      dispatch(getUserProducts({ page: 1, limit: 100 })); // Refresh product list
      handleActionsMenuClose();
    } catch (err) {
      alert(err?.message || "Failed to delete product");
    }
  };

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        background: "#f8fafc",
        px: { xs: 2, sm: 4, md: 7, lg: 12 },
        py: { xs: 2, sm: 4, md: 5 },
        boxSizing: "border-box",
        display: "flex",
        justifyContent: "center",
      }}
    >
      <Box
        sx={{
          maxWidth: 1400,
          width: "100%",
          mx: "auto",
          paddingRight: "10px",
          boxSizing: "border-box",
        }}
      >
        {/* Header */}
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            mb: 3,
          }}
        >
          <Typography
            variant={isMobile ? "h5" : "h4"}
            fontWeight={700}
            color="text.primary"
            sx={{ mb: isMobile ? 2 : 0 }}
          >
            Catalog Management
          </Typography>
          <Box sx={{ display: "flex", gap: 1 }}>
            <Button
              variant="outlined"
              startIcon={<CloudUploadOutlinedIcon />}
              sx={{
                bgcolor: "white",
                px: 1.5,
                minWidth: 36,
                fontWeight: 600,
                fontSize: 14,
                borderColor: "#95a4d7",
                "&:hover": {
                  bgcolor: "rgba(30, 94, 255, 0.1)",
                },
              }}
            >
              Upload PDF
            </Button>
            <Button
              variant="contained"
              startIcon={<AddCircleOutlineIcon />}
              sx={{
                bgcolor: "#1344a4",
                px: 2,
                minWidth: 110,
                fontWeight: 700,
                fontSize: 16,
                "&:hover": {
                  bgcolor: "#0e3877",
                },
              }}
              onClick={handleAddProductOpen}
            >
              Add Product
            </Button>
          </Box>
        </Box>
        <Box
          sx={{
            display: "flex",
            flexWrap: isMobile ? "wrap" : "nowrap",
            gap: 1,
            mb: 3,
            overflowX: isMobile ? "visible" : "auto",
          }}
        >
          {/* MRP Catalog - always visible */}
          <Button
            variant={
              selectedBuyerCategory === "MRP Catalog" ? "contained" : "outlined"
            }
            onClick={() => handleBuyerCategorySelect("MRP Catalog")}
            sx={{
              borderRadius: "40px",
              minWidth: 100,
              fontWeight: 700,
              px: 2,
              bgcolor:
                selectedBuyerCategory === "MRP Catalog" ? "#1344a4" : "white",
              color:
                selectedBuyerCategory === "MRP Catalog" ? "white" : "#1344a4",
            }}
          >
            MRP Catalog
          </Button>
          {/* First 4 buyer categories */}
          {visibleCategories.map((cat) => (
            <Button
              key={cat._id}
              variant={
                selectedBuyerCategory === cat.name ? "contained" : "outlined"
              }
              onClick={() => handleBuyerCategorySelect(cat)}
              sx={{
                borderRadius: "40px",
                minWidth: 100,
                fontWeight: 700,
                px: 2,
                bgcolor:
                  selectedBuyerCategory === cat.name ? "#1344a4" : "white",
                color: selectedBuyerCategory === cat.name ? "white" : "#1344a4",
              }}
            >
              {cat.name} {cat.discount && `| Discount: ${cat.discount}`}
            </Button>
          ))}

          {/* Add Buyer Category Button (now before More) */}
          <Button
            variant="outlined"
            sx={{
              borderRadius: "50%",
              minWidth: 40,
              minHeight: 40,
              color: "#1344a4",
              borderColor: "#1344a4",
            }}
            onClick={handleAddBuyerCategoryOpen}
          >
            <AddIcon />
          </Button>

          {/* More dropdown if extra exist */}
          {extraCategories.length > 0 && (
            <>
              <Button
                variant="outlined"
                onClick={handleMoreOpen}
                sx={{
                  borderRadius: "40px",
                  minWidth: 100,
                  fontWeight: 700,
                  px: 2,
                  color: "#1344a4",
                }}
              >
                More
              </Button>
              <Menu
                anchorEl={anchorMore}
                open={Boolean(anchorMore)}
                onClose={handleMoreClose}
              >
                {extraCategories.map(({ name, discount }) => (
                  <MenuItem
                    key={name}
                    onClick={() => {
                      handleBuyerCategorySelect(name);
                      handleMoreClose();
                    }}
                  >
                    {name} {discount && `| Discount: ${discount}`}
                  </MenuItem>
                ))}
              </Menu>
            </>
          )}
        </Box>

        {/* Product (Seller) Categories */}
        <Box
          sx={{
            display: "flex",
            flexWrap: isMobile ? "wrap" : "nowrap",
            gap: 1,
            mb: 3,
            overflowX: isMobile ? "visible" : "auto",
          }}
        >
          {/* All always visible */}
          <Button
            variant={selectedCategory === "All" ? "contained" : "outlined"}
            onClick={() => setSelectedCategory("All")}
            sx={{ borderRadius: "40px", minWidth: 80, fontWeight: 700, px: 2 }}
          >
            All
          </Button>

          {/* First 4 seller categories */}
          {visibleSellerCategories.map((cat) => (
            <Button
              key={cat._id}
              variant={
                selectedCategory?.name === cat.name ? "contained" : "outlined"
              }
              onClick={() => setSelectedCategory(cat)}
              sx={{
                borderRadius: "40px",
                minWidth: 120,
                fontWeight: 700,
                px: 2,
              }}
            >
              {cat.name} {cat.gst ? `: ${cat.gst}` : ""}
            </Button>
          ))}

          {/* Add button */}
          <Button
            variant="outlined"
            sx={{
              borderRadius: "50%",
              minWidth: 40,
              minHeight: 40,
              color: "#1344a4",
              borderColor: "#1344a4",
            }}
            onClick={handleAddProductCategoryOpen}
          >
            <AddIcon />
          </Button>

          {/* More dropdown */}
          {extraSellerCategories.length > 0 && (
            <>
              <Button
                variant="outlined"
                onClick={handleMoreSellerOpen}
                sx={{
                  borderRadius: "40px",
                  minWidth: 100,
                  fontWeight: 700,
                  px: 2,
                }}
              >
                More
              </Button>
              <Menu
                anchorEl={anchorMoreSeller}
                open={Boolean(anchorMoreSeller)}
                onClose={handleMoreSellerClose}
              >
                {extraSellerCategories.map((cat) => (
                  <MenuItem
                    key={cat._id}
                    onClick={() => {
                      setSelectedCategory(cat);
                      handleMoreSellerClose();
                    }}
                  >
                    {cat.name} {cat.gst ? `: ${cat.gst}` : ""}
                  </MenuItem>
                ))}
              </Menu>
            </>
          )}
        </Box>

        {/* Product Table */}
        <Box sx={{ overflowX: "auto" }}>
          <TableContainer>
            <Box sx={{ overflowX: "auto" }}>
              <TableContainer>
                <Table stickyHeader sx={{ minWidth: 650 }}>
                  <TableHead>
                    <TableRow>
                      <TableCell>Image</TableCell>
                      <TableCell>Name</TableCell>
                      <TableCell>Category</TableCell>

                      {selectedBuyerCategory === "MRP Catalog" ? (
                        //  MRP Catalog headers
                        <>
                          <TableCell>MRP</TableCell>
                          <TableCell>Stock</TableCell>
                        </>
                      ) : (
                        //  Other buyer categories headers
                        <>
                          <TableCell>MRP</TableCell>
                          <TableCell>Price</TableCell>
                          <TableCell>Stock</TableCell>
                          <TableCell>Visible</TableCell>
                          <TableCell>Actions</TableCell>
                        </>
                      )}
                    </TableRow>
                  </TableHead>

                  <TableBody>
                    {filteredProducts?.map((product) => {
                      const buyerProduct =
                        productsByBuyerCategory?.products?.find(
                          (p) => p._id === product._id
                        );

                      const priceToShow =
                        buyerProduct?.buyerCategory?.price ?? product.price;

                      return (
                        <TableRow key={product._id}>
                          {/* Image */}
                          <TableCell>
                            <Box
                              sx={{
                                width: 40,
                                height: 40,
                                bgcolor: "#e7fafc",
                                color: "#a0b7a8",
                                fontWeight: 700,
                                fontSize: 15,
                                borderRadius: 2,
                                display: "flex",
                                justifyContent: "center",
                                alignItems: "center",
                              }}
                            >
                              {product.image ? (
                                <img
                                  src={product.image}
                                  alt={product.name}
                                  style={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    borderRadius: 8,
                                  }}
                                />
                              ) : (
                                "IMG"
                              )}
                            </Box>
                          </TableCell>

                          {/* Name */}
                          <TableCell
                            sx={{
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                            }}
                          >
                            {product.name}
                          </TableCell>

                          {/* Category */}
                          <TableCell>{product.category?.name}</TableCell>

                          {selectedBuyerCategory === "MRP Catalog" ? (
                            <>
                              <TableCell>{product.mrp?.toFixed(2)}</TableCell>
                              <TableCell>
                                {product.stock === 0 ? (
                                  <Box
                                    sx={{
                                      bgcolor: "#f8d7da",
                                      color: "#842029",
                                      borderRadius: 2,
                                      py: 0.5,
                                      px: 1,
                                      fontWeight: 600,
                                    }}
                                  >
                                    Out of Stock
                                  </Box>
                                ) : (
                                  <Box
                                    sx={{
                                      bgcolor: "#d1f7dd",
                                      color: "#0f6532",
                                      borderRadius: 2,
                                      py: 0.5,
                                      px: 1,
                                      fontWeight: 600,
                                    }}
                                  >
                                    {product.stock} units
                                  </Box>
                                )}
                              </TableCell>
                            </>
                          ) : (
                            <>
                              <TableCell>{product.mrp?.toFixed(2)}</TableCell>
                              <TableCell>{priceToShow?.toFixed(2)}</TableCell>

                              <TableCell>
                                {product.stock === 0 ? (
                                  <Box
                                    sx={{
                                      bgcolor: "#f8d7da",
                                      color: "#842029",
                                      borderRadius: 2,
                                      py: 0.5,
                                      px: 1,
                                      fontWeight: 600,
                                    }}
                                  >
                                    Out of Stock
                                  </Box>
                                ) : (
                                  <Box
                                    sx={{
                                      bgcolor: "#d1f7dd",
                                      color: "#0f6532",
                                      borderRadius: 2,
                                      py: 0.5,
                                      px: 1,
                                      fontWeight: 600,
                                    }}
                                  >
                                    {product.stock} units
                                  </Box>
                                )}
                              </TableCell>
                              <TableCell>
                                <Switch
                                  checked={!!product.productVisibility} // ensures boolean true/false
                                  disabled={product.stock === 0}
                                  onChange={() =>
                                    handleToggleProductVisible(
                                      product._id,
                                      product.productVisibility, // ✅ no fallback to true
                                      selectedBuyerCategoryId
                                    )
                                  }
                                  color="primary"
                                  size="small"
                                />
                              </TableCell>
                              <TableCell>
                                <IconButton
                                  onClick={(e) =>
                                    handleActionsMenuOpen(e, product._id)
                                  }
                                  size="small"
                                  sx={{ p: 0.5 }}
                                >
                                  <MoreHorizIcon />
                                </IconButton>
                                <Menu
                                  anchorEl={anchorEl}
                                  open={
                                    actionProductId === product._id &&
                                    Boolean(anchorEl)
                                  }
                                  onClose={handleActionsMenuClose}
                                  anchorOrigin={{
                                    vertical: "bottom",
                                    horizontal: "right",
                                  }}
                                  transformOrigin={{
                                    vertical: "top",
                                    horizontal: "right",
                                  }}
                                >
                                  <MenuItem
                                    onClick={() =>
                                      handleEditProductOpen(product)
                                    }
                                  >
                                    <ListItemIcon>
                                      <EditIcon fontSize="small" />
                                    </ListItemIcon>
                                    <ListItemText>Edit</ListItemText>
                                  </MenuItem>
                                  <MenuItem
                                    onClick={() =>
                                      handleDeleteProduct(product._id)
                                    }
                                  >
                                    <ListItemIcon>
                                      <DeleteIcon
                                        fontSize="small"
                                        color="error"
                                      />
                                    </ListItemIcon>
                                    <ListItemText>Delete</ListItemText>
                                  </MenuItem>
                                </Menu>
                              </TableCell>
                            </>
                          )}
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          </TableContainer>
        </Box>
      </Box>

      {/* Add Product Dialog */}
      <Dialog
        open={openAddProduct}
        onClose={handleAddProductClose}
        fullWidth
        maxWidth="sm"
        scroll="body"
      >
        <DialogTitle>
          Add Product
          <IconButton
            onClick={handleAddProductClose}
            sx={{ position: "absolute", right: 12, top: 12 }}
            size="small"
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ px: { xs: 1, sm: 3 }, py: 2 }} dividers>
          <Box
            component="form"
            onSubmit={handleAddProductSubmit}
            sx={{ display: "flex", flexDirection: "column", gap: 2 }}
          >
            <TextField
              label="Product Category"
              name="category"
              value={newProduct.category}
              onChange={handleAddProductChange}
              select
              required
              fullWidth
              size="small"
            >
              {sellerCategories?.map((cat) => (
                <MenuItem key={cat?._id} value={cat?._id}>
                  {cat.name}
                </MenuItem>
              ))}
            </TextField>

            <TextField
              label="Product Name"
              name="name"
              value={newProduct.name}
              onChange={handleAddProductChange}
              required
              fullWidth
              size="small"
            />
            <TextField
              label="MRP"
              name="mrp"
              value={newProduct.mrp}
              onChange={handleAddProductChange}
              type="number"
              required
              fullWidth
              size="small"
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">₹</InputAdornment>
                ),
              }}
            />
            <TextField
              label="Stock"
              name="stock"
              value={newProduct.stock}
              onChange={handleAddProductChange}
              type="number"
              required
              fullWidth
              size="small"
            />
            <TextField
              label="Description"
              name="description"
              value={newProduct.description}
              onChange={handleAddProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />
            <TextField
              label="Specifications"
              name="specifications"
              value={newProduct.specifications}
              onChange={handleAddProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />
            <TextField
              type="file"
              inputProps={{ accept: "image/*" }}
              onChange={(e) => {
                const file = e.target.files[0];
                if (file) {
                  const reader = new FileReader();
                  reader.onloadend = () => {
                    setNewProduct((prev) => ({
                      ...prev,
                      image: reader.result,
                    })); // Base64 string
                  };
                  reader.readAsDataURL(file);
                }
              }}
              fullWidth
              size="small"
            />
            <DialogActions sx={{ px: 0 }}>
              <Button onClick={handleAddProductClose}>Cancel</Button>
              <Button type="submit" variant="contained">
                Add Product
              </Button>
            </DialogActions>
          </Box>
        </DialogContent>
      </Dialog>

      {/*  Edit Product Dialog */}
      <Dialog
        open={openEditProduct}
        onClose={handleEditProductClose}
        fullWidth
        maxWidth="sm"
        scroll="body"
      >
        <DialogTitle>
          Edit Product
          <IconButton
            onClick={handleEditProductClose}
            sx={{ position: "absolute", right: 12, top: 12 }}
            size="small"
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ px: { xs: 1, sm: 3 }, py: 2 }} dividers>
          <Box
            component="form"
            onSubmit={handleEditProductSubmit}
            sx={{ display: "flex", flexDirection: "column", gap: 2 }}
          >
            {/* Product Name */}
            <TextField
              label="Product Name"
              name="name"
              value={editProduct.name}
              onChange={handleEditProductChange}
              required
              fullWidth
              size="small"
            />

            {/* Seller Categories */}
            <TextField
              label="Category"
              name="category"
              value={editProduct.category?.name || ""}
              onChange={handleEditProductChange}
              select
              required
              fullWidth
              size="small"
            >
              {sellerCategories?.map((cat) => (
                <MenuItem
                  key={cat._id}
                  value={cat.name} // display name
                  onClick={
                    () => setEditProduct((prev) => ({ ...prev, category: cat })) // save full object
                  }
                >
                  {cat.name}
                </MenuItem>
              ))}
            </TextField>

            <TextField
              label="MRP"
              name="mrp"
              value={editProduct.mrp}
              onChange={handleEditProductChange}
              type="number"
              required
              fullWidth
              size="small"
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">₹</InputAdornment>
                ),
              }}
            />

            {/* Price */}
            <TextField
              label="Price"
              name="price"
              value={editProduct.price}
              onChange={handleEditProductChange}
              type="number"
              required
              fullWidth
              size="small"
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">₹</InputAdornment>
                ),
              }}
            />
            {/* Stock */}
            <TextField
              label="Stock"
              name="stock"
              value={editProduct.stock}
              onChange={handleEditProductChange}
              type="number"
              required
              fullWidth
              size="small"
            />

            <TextField
              label="Description"
              name="description"
              value={editProduct.description}
              onChange={handleEditProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />
            <TextField
              label="Specifications"
              name="specifications"
              value={editProduct.specifications}
              onChange={handleEditProductChange}
              multiline
              rows={3}
              fullWidth
              size="small"
              placeholder="Optional"
            />

            <TextField
              type="file"
              inputProps={{ accept: "image/*" }}
              onChange={(e) => {
                const file = e.target.files[0];
                if (file) {
                  const objectUrl = URL.createObjectURL(file);
                  setEditProduct((prev) => ({
                    ...prev,
                    image: objectUrl,
                    imageFile: file,
                  }));
                } else {
                  setEditProduct((prev) => ({
                    ...prev,
                    image: "",
                    imageFile: null,
                  }));
                }
              }}
              fullWidth
              size="small"
            />

            {/* Preview */}
            {editProduct.image && (
              <Box
                sx={{
                  width: 80,
                  height: 80,
                  borderRadius: 2,
                  overflow: "hidden",
                  mt: 1,
                }}
              >
                <img
                  src={editProduct.image}
                  alt="Preview"
                  style={{ width: "100%", height: "100%", objectFit: "cover" }}
                />
              </Box>
            )}
            <DialogActions sx={{ px: 0 }}>
              <Button onClick={handleEditProductClose}>Cancel</Button>
              <Button type="submit" variant="contained">
                Save Changes
              </Button>
            </DialogActions>
          </Box>
        </DialogContent>
      </Dialog>

      {/* Add Buyer Category Dialog */}
      <AddBuyerCategoryDialog
        open={openAddBuyerCategory}
        handleClose={handleAddBuyerCategoryClose}
        newBuyerCategory={newBuyerCategory}
        handleChange={handleAddBuyerCategoryChange}
        handleSubmit={handleAddBuyerCategorySubmit}
      />

      {/* Add Seller Category Dialog */}
      <AddSellerCategoryDialog
        open={openAddProductCategory}
        handleClose={handleAddProductCategoryClose}
        newSellerCategory={newProductCategory}
        handleChange={handleAddProductCategoryChange}
        handleSubmit={handleAddProductCategorySubmit}
      />
    </Box>
  );
}
