import React, { useEffect, useState } from "react";
import {
  Avatar,
  Box,
  IconButton,
  InputAdornment,
  Typography,
  Breadcrumbs,
  Link as MUILink,
} from "@mui/material";
import { Visibility, VisibilityOff } from "@mui/icons-material";
import TextField from "@mui/material/TextField";
import Button from "@mui/material/Button";

import { useDispatch, useSelector } from "react-redux";
import { Link, useLocation, useNavigate } from "react-router-dom";
import Password from "@mui/icons-material/Password";
import { message } from "antd";
import {
  resetPassword,
  clearErrors,
  resetPasswordUpdate,
} from "../redux/slices/userSlice";

const ResetPassword = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  // const { error, success, loading } = useSelector((state) => state.user);

  const { loading, success, error } = useSelector(
  (state) => state.user.operations.passwordUpdate
);


  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);

  // Toggle password visibility
  const handleClickShowPassword = () => {
    setShowPassword(!showPassword);
  };

  const handleClickShowNewPassword = () => {
    setShowNewPassword(!showNewPassword);
  };
  const location = useLocation();
  // const token = location.state?.resetPasswordToken;
  const token = location.state?.token;

  // const handleSubmit = (e) => {
  //   e.preventDefault();
  //   const myForm = new FormData();
  //   myForm.set("password", password);
  //   myForm.set("confirmPassword", confirmPassword);
  //   myForm.set("token", token);
  //   const result = dispatch(resetPassword({ passwords: myForm }));
  //   if (resetPassword.fulfilled.match(result)) {
  //     message.success("Password has been reset successfully!");
  //     dispatch(resetPasswordUpdate()); // clear success for next operation
  //   } else {
  //     message.error(result.payload || "Failed to reset password");
  //   }
  // };

  // useEffect(() => {
  //   if (error) {
  //     message.error(error);
  //     dispatch(clearErrors());
  //   }
  //   if (success) {
  //     message.success("Password Updated Successfully");
  //     navigate("/login");
  //   }
  //   // This line is correct as long as navigate is stable (it is with react-router v6+)
  // }, [dispatch, error, success]);


  const handleSubmit = async (e) => {
  e.preventDefault();

  const myForm = new FormData();
  myForm.set("password", password);
  myForm.set("confirmPassword", confirmPassword);
  myForm.set("token", token);

  const resultAction = await dispatch(resetPassword({ passwords: myForm }));

  if (resetPassword.fulfilled.match(resultAction)) {
    message.success("Password has been reset successfully!");
    dispatch(resetPasswordUpdate());
    navigate("/login");
  } else {
    message.error(resultAction.payload || "Failed to reset password");
  }
};

  // useEffect(() => {
  //   console.log("Redux state.user:", { error, success, loading });
  //   if (error) {
  //     message.error(error);
  //     dispatch(clearErrors());
  //   }
  //   if (success) {
  //     message.success("Password Updated Successfully");
  //     navigate("/login");
  //   }
  // }, [dispatch, error, success]);

  const currentYear = new Date().getFullYear();

  return (
    <div>
      <Breadcrumbs
        aria-label="breadcrumb"
        sx={{
          backgroundColor: "#fff",
          padding: "20px",
          borderRadius: "12px",
          boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
        }}
      >
        <MUILink
          component={Link}
          to="/"
          sx={{ color: "inherit", textDecoration: "none" }}
        >
          Home
        </MUILink>
        <Typography sx={{ color: "primary.main" }}>Reset Password</Typography>
      </Breadcrumbs>
      <Box
        sx={{
          height: "100vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          bgcolor: "primary.white",
        }}
      >
        <Box
          onSubmit={handleSubmit}
          component="form"
          className="form_style border-style"
          sx={{
            backgroundColor: "#fff",
            padding: "40px",
            borderRadius: "12px",
            boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
            maxWidth: "400px",
            width: "100%",
            textAlign: "center",
          }}
        >
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              width: "100%",
            }}
          >
            <Avatar sx={{ m: 1, bgcolor: "primary.main", mb: 3 }}>
              <Password />
            </Avatar>
            <Typography
              variant="h5"
              align="center"
              gutterBottom
              sx={{
                fontFamily: "Poppins, sans-serif",
                color: "#333",
                letterSpacing: "2.5px",
                lineHeight: 1.8,
              }}
            >
              Reset Password
            </Typography>

            <TextField
              sx={{
                mb: 3,
                mt: 3,
                "& .MuiInputBase-root": {
                  color: "text.secondary",
                },
                fieldset: { borderColor: "rgb(231, 235, 240)" },
              }}
              fullWidth
              id="password"
              name="password"
              label="New Password"
              type={showNewPassword ? "text" : "password"}
              placeholder="New Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={handleClickShowNewPassword} edge="end">
                      {showNewPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            <TextField
              sx={{
                mb: 3,
                "& .MuiInputBase-root": {
                  color: "text.secondary",
                },
                fieldset: { borderColor: "rgb(231, 235, 240)" },
              }}
              fullWidth
              id="ConfirmPassword"
              name="password"
              label="Confirm Password"
              type={showPassword ? "text" : "password"}
              placeholder="Confirm Password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={handleClickShowPassword} edge="end">
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            <Button
              disabled={loading}
              fullWidth
              variant="contained"
              type="submit"
              color="primary"
              className="courses_desc"
              sx={{
                borderRadius: "5px",
                textTransform: "none",
                fontFamily: "Poppins, sans-serif",
                letterSpacing: ".1rem",
                color: "white",
              }}
            >
              {loading ? "loading..." : "Reset Password"}
            </Button>
            <hr style={{ marginTop: "20px" }} />
            <p
              style={{
                marginTop: "20px",
                fontSize: "12px",
                letterSpacing: ".1rem",
                lineHeight: "1.5rem",
                marginBottom: "-20px",
              }}
            >
              &copy; {currentYear} Copyright by Bizbridge. All rights reserved.
            </p>
          </Box>
        </Box>
      </Box>
    </div>
  );
};

export default ResetPassword;
